scwin.gLdMktTp = js_market;
scwin.vCHAR1_CHANGED = "F";
scwin.vCHAR2_CHANGED = "F";
scwin.vCHAR3_CHANGED = "F";
scwin.vCHAR4_CHANGED = "F";
scwin.vScrenID = "ULDSTF30604.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Search = function() {
    var parentWin = $c.frame.path("../");
    var paramObj = parentWin.gParamObj;
    if (paramObj == undefined) return;
    $c.stf.setObjectValue(txb_ISUR_CD, paramObj.param1);
    $c.stf.setObjectValue(txb_COM_NM, paramObj.param2);
    var vISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    var vICHRG_TP_CD1 = "41";
    var vICHRG_TP_CD2 = "42";
    var vICHRG_TP_CD3 = "43";
    var vICHRG_TP_CD4 = "44";
    if (scwin.gLdMktTp == "6") {
        // 코넥스 일경우 변경
        var vICHRG_TP_CD1 = "81";
        var vICHRG_TP_CD2 = "";
        var vICHRG_TP_CD3 = "";
        var vICHRG_TP_CD4 = "82";
    }
    var url = "/ListedCompany.do?method=readCompanyPersonInCharge1";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&CHRG_TP_CD=" + vICHRG_TP_CD1;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_CHRG1.DataID = encodeURI(url);
    dts_CHRG1.Reset();
    var url = "/ListedCompany.do?method=readCompanyPersonInCharge1";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&CHRG_TP_CD=" + vICHRG_TP_CD2;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_CHRG2.DataID = encodeURI(url);
    dts_CHRG2.Reset();
    var url = "/ListedCompany.do?method=readCompanyPersonInCharge1";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&CHRG_TP_CD=" + vICHRG_TP_CD3;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_CHRG3.DataID = encodeURI(url);
    dts_CHRG3.Reset();
    var url = "/ListedCompany.do?method=readCompanyPersonInCharge1";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&CHRG_TP_CD=" + vICHRG_TP_CD4;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_CHRG4.DataID = encodeURI(url);
    dts_CHRG4.Reset();

    //dts_CHRG1/2/3 이 없을 경우 값이 없어져버리므로 다시 세팅 해준다. (YSH,  2008/09/30) 
    $c.stf.setObjectValue(txb_ISUR_CD, paramObj.param1);
    txb_DEP_NM1.setDisabled(true);
    txb_JOBTITL_NM1.setDisabled(true);
    txb_TEL_NO1.setDisabled(true);
    txb_CELLPHONE_NO1.setDisabled(true);
    txb_FAX_NO1.setDisabled(true);
    txb_EMAIL1.setDisabled(true);
    txb_LOC_DTL_ADDR1.setDisabled(true);
    txb_DEP_NM2.setDisabled(true);
    txb_JOBTITL_NM2.setDisabled(true);
    txb_TEL_NO2.setDisabled(true);
    txb_CELLPHONE_NO2.setDisabled(true);
    txb_FAX_NO2.setDisabled(true);
    txb_EMAIL2.setDisabled(true);
    txb_LOC_DTL_ADDR2.setDisabled(true);
    txb_DEP_NM3.setDisabled(true);
    txb_JOBTITL_NM3.setDisabled(true);
    txb_TEL_NO3.setDisabled(true);
    txb_CELLPHONE_NO3.setDisabled(true);
    txb_FAX_NO3.setDisabled(true);
    txb_EMAIL3.setDisabled(true);
    txb_LOC_DTL_ADDR3.setDisabled(true);
    txb_DEP_NM4.setDisabled(true);
    txb_JOBTITL_NM4.setDisabled(true);
    txb_TEL_NO4.setDisabled(true);
    txb_CELLPHONE_NO4.setDisabled(true);
    txb_FAX_NO4.setDisabled(true);
    txb_EMAIL4.setDisabled(true);
    txb_LOC_DTL_ADDR4.setDisabled(true);
};
scwin.fn_Save = function() {
    /*
	alert(vCHAR1_CHANGED );
	alert(vCHAR2_CHANGED );
	alert(vCHAR3_CHANGED );
	return;
	*/
    if (confirm("수정처리하시겠습니까?")) {
        dts_CHRG1.UseChangeInfo = "true";
        dts_CHRG2.UseChangeInfo = "true";
        dts_CHRG3.UseChangeInfo = "true";
        dts_CHRG4.UseChangeInfo = "true";
        // 수정여부 플래그 박기.
        dts_CHRG1.setCellData(1, "CHAR_CHANGED", scwin.vCHAR1_CHANGED);
        dts_CHRG2.setCellData(1, "CHAR_CHANGED", scwin.vCHAR2_CHANGED);
        dts_CHRG3.setCellData(1, "CHAR_CHANGED", scwin.vCHAR3_CHANGED);
        dts_CHRG4.setCellData(1, "CHAR_CHANGED", scwin.vCHAR4_CHANGED);
        trs_Save.Action = "/ListedCompany.do?method=modifyCompanyPersonInCharge" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_CHRG1,I:pInput2=dts_CHRG2,I:pInput3=dts_CHRG3,I:pInput4=dts_CHRG4)";
        trs_Save.Post();
    } else {
        return false;
    }
};
scwin.fn_Control1 = function() {
    vCHRG_TP_CD1 = $c.stf.getObjectValue(chb_CHRG_TP_CD1);
    if (vCHRG_TP_CD1 == "Y") {
        txb_DEP_NM1.setDisabled(false);
        txb_JOBTITL_NM1.setDisabled(false);
        txb_TEL_NO1.setDisabled(false);
        txb_CELLPHONE_NO1.setDisabled(false);
        txb_FAX_NO1.setDisabled(false);
        txb_EMAIL1.setDisabled(false);
        txb_LOC_ADDR1.setDisabled(false);
        txb_LOC_DTL_ADDR1.setDisabled(false);
    }
    if (vCHRG_TP_CD1 == "N") {
        txb_DEP_NM1.setDisabled(true);
        txb_JOBTITL_NM1.setDisabled(true);
        txb_TEL_NO1.setDisabled(true);
        txb_CELLPHONE_NO1.setDisabled(true);
        txb_FAX_NO1.setDisabled(true);
        txb_EMAIL1.setDisabled(true);
        txb_LOC_ADDR1.setDisabled(true);
        txb_LOC_DTL_ADDR1.setDisabled(true);
    }
};
