scwin.fn_HideDebugCtrls = function() {
    $c.stf.showObj(panel_debug, false);
};
scwin.fn_Init = function() {
    if (scwin.gLdMktTp == "6") {
        // 코넥스 일경우 체크박스 2개 disabled 처리
        chb_CHRG_TP_CD2.setDisabled("true");
        checkbox_2.setDisabled("true");
        chb_CHRG_TP_CD3.setDisabled("true");
        checkbox_3.setDisabled("true");
    }
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save); ///('trs_Save.OnFail()');

};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert("수정하였습니다.");
    var fr_fn_Search = $c.frame.path("../").fn_tab1_Search;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
